import plotly.graph_objects as go
import json

# Load source data
with open('/app/benchmark/source_data.json') as f:
    data = json.load(f)['energy_sankey']

nodes = data['nodes']
flows = data['flows']

# Build node index
node_ids = [n['id'] for n in nodes]
node_labels = [n['label'] for n in nodes]
node_stage = {n['id']: n['stage'] for n in nodes}
node_idx = {n['id']: i for i, n in enumerate(nodes)}

# Color scheme by node type
def node_color(node_id, stage):
    fossil = {'oil', 'coal', 'natural_gas'}
    renewable = {'hydro', 'wind', 'solar', 'biomass', 'geothermal'}
    nuclear = {'nuclear'}
    transformation = {'thermal_power', 'refining', 'direct_use', 'electricity_grid'}
    end_use = {'transport', 'industry', 'buildings', 'agriculture', 'other'}
    waste = {'waste_heat'}

    if node_id in fossil:
        return '#C0392B'      # dark red - fossil fuels
    elif node_id in nuclear:
        return '#8E44AD'      # purple - nuclear
    elif node_id in renewable:
        return '#27AE60'      # green - renewables
    elif node_id == 'thermal_power':
        return '#E67E22'      # orange
    elif node_id == 'refining':
        return '#D35400'      # darker orange
    elif node_id == 'direct_use':
        return '#F39C12'      # amber
    elif node_id == 'electricity_grid':
        return '#2980B9'      # blue
    elif node_id in end_use:
        return '#2C3E50'      # dark navy
    elif node_id in waste:
        return '#E74C3C'      # bright red - waste heat highlight
    return '#95A5A6'

# Flow colors: highlight waste heat flows in warm red, fossil in warm tones, renewables in green
def flow_color(source, target):
    fossil = {'oil', 'coal', 'natural_gas'}
    renewable = {'hydro', 'wind', 'solar', 'biomass', 'geothermal'}

    if target == 'waste_heat':
        return 'rgba(231, 76, 60, 0.55)'   # warm red - waste heat highlight
    elif source in fossil:
        return 'rgba(192, 57, 43, 0.35)'   # fossil red
    elif source == 'nuclear':
        return 'rgba(142, 68, 173, 0.35)'  # nuclear purple
    elif source in renewable:
        return 'rgba(39, 174, 96, 0.45)'   # renewable green
    elif source == 'thermal_power':
        return 'rgba(230, 126, 34, 0.35)'
    elif source == 'refining':
        return 'rgba(211, 84, 0, 0.35)'
    elif source == 'direct_use':
        return 'rgba(243, 156, 18, 0.35)'
    elif source == 'electricity_grid':
        return 'rgba(41, 128, 185, 0.45)'
    return 'rgba(149, 165, 166, 0.3)'

node_colors = [node_color(n['id'], n['stage']) for n in nodes]

sources = [node_idx[f['source']] for f in flows]
targets = [node_idx[f['target']] for f in flows]
values  = [f['value'] for f in flows]
link_colors = [flow_color(f['source'], f['target']) for f in flows]

# Custom node x positions (0=left, 1=right) to enforce 3 stages
stage_x = {'primary': 0.01, 'transformation': 0.45, 'end_use': 0.92}
node_x = [stage_x[node_stage[n['id']]] for n in nodes]

# Distribute y positions within each stage
from collections import defaultdict
stage_nodes = defaultdict(list)
for n in nodes:
    stage_nodes[n['stage']].append(n['id'])

node_y = [0.5] * len(nodes)
for stage, nids in stage_nodes.items():
    count = len(nids)
    for i, nid in enumerate(nids):
        node_y[node_idx[nid]] = (i + 1) / (count + 1)

hover_labels = []
for n in nodes:
    in_flow = sum(f['value'] for f in flows if f['target'] == n['id'])
    out_flow = sum(f['value'] for f in flows if f['source'] == n['id'])
    if in_flow > 0 and out_flow > 0:
        hover_labels.append(f"{n['label']}<br>In: {in_flow:.1f} EJ<br>Out: {out_flow:.1f} EJ")
    elif in_flow > 0:
        hover_labels.append(f"{n['label']}<br>Total: {in_flow:.1f} EJ")
    else:
        hover_labels.append(f"{n['label']}<br>Total: {out_flow:.1f} EJ")

fig = go.Figure(go.Sankey(
    arrangement='snap',
    node=dict(
        pad=18,
        thickness=22,
        line=dict(color='rgba(255,255,255,0.4)', width=0.5),
        label=node_labels,
        color=node_colors,
        customdata=hover_labels,
        hovertemplate='%{customdata}<extra></extra>',
        x=node_x,
        y=node_y,
    ),
    link=dict(
        source=sources,
        target=targets,
        value=values,
        color=link_colors,
        hovertemplate='%{source.label} → %{target.label}<br>%{value:.1f} EJ<extra></extra>',
    )
))

fig.update_layout(
    title=dict(
        text=(
            "<b>Global Energy Flow — 2022 (Approximate)</b><br>"
            "<sup style='color:#666'>Primary Sources → Transformation → End Use  |  Band width ∝ Energy (EJ)  |  "
            "Waste/Rejected Heat (~167.7 EJ) exceeds all renewable inputs combined (~73.7 EJ)</sup>"
        ),
        x=0.5,
        xanchor='center',
        font=dict(size=17, family='Arial, sans-serif'),
    ),
    font=dict(size=12, family='Arial, sans-serif', color='#1a1a2e'),
    paper_bgcolor='#F8F9FA',
    plot_bgcolor='#F8F9FA',
    width=1400,
    height=780,
    margin=dict(l=20, r=20, t=100, b=60),
    annotations=[
        dict(
            x=0.01, y=-0.07, xref='paper', yref='paper',
            text='<b>Primary Energy Sources</b>',
            showarrow=False, font=dict(size=12, color='#444'), xanchor='left',
        ),
        dict(
            x=0.45, y=-0.07, xref='paper', yref='paper',
            text='<b>Transformation</b>',
            showarrow=False, font=dict(size=12, color='#444'), xanchor='center',
        ),
        dict(
            x=0.92, y=-0.07, xref='paper', yref='paper',
            text='<b>End Use</b>',
            showarrow=False, font=dict(size=12, color='#444'), xanchor='center',
        ),
        # Legend annotations
        dict(
            x=0.01, y=1.0, xref='paper', yref='paper',
            text=(
                '<span style="color:#C0392B">■</span> Fossil Fuels&nbsp;&nbsp;'
                '<span style="color:#8E44AD">■</span> Nuclear&nbsp;&nbsp;'
                '<span style="color:#27AE60">■</span> Renewables&nbsp;&nbsp;'
                '<span style="color:#E74C3C">■</span> Waste/Rejected Heat'
            ),
            showarrow=False, font=dict(size=11, color='#333'),
            xanchor='left', align='left',
        ),
        dict(
            x=0.99, y=-0.07, xref='paper', yref='paper',
            text='Source: IEA / LLNL-style global energy estimates, 2022',
            showarrow=False, font=dict(size=10, color='#888'), xanchor='right',
        ),
    ]
)

import os
os.makedirs('/app/output', exist_ok=True)
fig.write_image('/app/output/result.png', width=1400, height=780, scale=2)
print("Saved /app/output/result.png")

